package com.bank.framing;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class BracketValidatorDemo {

    private static final Logger log = Logger.getLogger(BracketValidatorDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BracketValidator validator = new BracketValidator();

        String good = "{[()]}";   // well-framed message segments
        String bad = "{[(])}";    // crossed brackets — invalid nesting

        log.info(() -> "Message '" + good + "' balanced? " + validator.isBalanced(good));
        log.info(() -> "Message '" + bad + "' balanced? " + validator.isBalanced(bad));
    }
}

// ─── Would be in service/BracketValidator.java in a real project ───
class BracketValidator {

    private static final Logger log = Logger.getLogger(BracketValidator.class.getName());

    // Each closer maps to the opener it must match.
    private static final java.util.Map<Character, Character> PAIRS =
            java.util.Map.of(')', '(', ']', '[', '}', '{');

    boolean isBalanced(String s) {
        java.util.Deque<Character> stack = new java.util.ArrayDeque<>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(' || c == '[' || c == '{') {
                stack.push(c);                       // opener → spike it
                final char pc = c;
                log.fine(() -> "  push " + pc + " depth=" + stack.size());
            } else {
                // Closer: must have a matching opener on top.
                if (stack.isEmpty() || stack.pop() != PAIRS.get(c)) {
                    log.warning(() -> "  mismatch at '" + c + "' — invalid framing");
                    return false;
                }
                log.fine(() -> "  pop matched " + c + " depth=" + stack.size());
            }
        }
        return stack.isEmpty();                      // dangling openers → invalid
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
